// Placeholders generated by tools/gen_appkit_stubs.py: classes exist with the superclass the headers name, property
// pairs keep their value (also structs, doubles, booleans, objects), +shared... answers one instance, nothing crashes.
// XEF-only (real AppKit behaves differently): built on Linux by build.sh, run under xef-osx.
typedef signed char BOOL;
typedef struct objc_class *Class;
typedef struct objc_object *id;
typedef struct objc_selector *SEL;
typedef struct { double x, y; } Pt;
typedef struct { double w, h; } Sz;
typedef struct { Pt o; Sz s; } Rc;
extern int printf(const char *, ...);
extern int strcmp(const char *, const char *);
extern id objc_getClass(const char *);
extern Class class_getSuperclass(Class);
extern const char *class_getName(Class);
extern id objc_msgSend(id, SEL, ...);
extern SEL sel_registerName(const char *);

@interface NSObject
+ (id)alloc;
- (id)init;
@end
@interface NSToolbar : NSObject
- (id)initWithIdentifier:(id)i;
- (BOOL)allowsUserCustomization; - (void)setAllowsUserCustomization:(BOOL)f;
- (BOOL)isVisible; - (void)setVisible:(BOOL)f;
- (long)displayMode; - (void)setDisplayMode:(long)m;
- (id)items;
@end
@interface NSPopover : NSObject
- (Sz)contentSize; - (void)setContentSize:(Sz)s;
- (BOOL)animates; - (void)setAnimates:(BOOL)f;
- (id)delegate; - (void)setDelegate:(id)d;
- (Rc)positioningRect; - (void)setPositioningRect:(Rc)r;
- (void)close;
@end
@interface NSSpellChecker : NSObject
+ (id)sharedSpellChecker;
- (double)spellCheckerDocumentTag_unused;
@end
@interface NSView : NSObject
- (double)alphaValue;
@end

static int fails;
#define CHECK(c) do { if (!(c)) { printf("FAIL: %s\n", #c); fails++; } } while (0)

int main(void) {
    Class tb = (Class)objc_getClass("NSToolbar");
    CHECK(tb != 0);
    CHECK(tb && class_getSuperclass(tb) == (Class)objc_getClass("NSObject"));
    NSToolbar *t = [[NSToolbar alloc] initWithIdentifier:0];
    CHECK(t != 0);
    CHECK([t allowsUserCustomization] == 0);
    [t setAllowsUserCustomization:1]; CHECK([t allowsUserCustomization] == 1);
    CHECK([t isVisible] == 0); [t setVisible:1]; CHECK([t isVisible] == 1);   // setVisible: and isVisible are one property
    [t setDisplayMode:3]; CHECK([t displayMode] == 3);
    CHECK([t items] != 0);                                                     // an NSArray result is an empty array, not nil
    NSPopover *p = [[NSPopover alloc] init];
    Sz s = [p contentSize]; CHECK(s.w == 0 && s.h == 0);
    Sz in = {320.5, 240.25}; [p setContentSize:in]; s = [p contentSize]; CHECK(s.w == 320.5 && s.h == 240.25);
    Rc r = {{1, 2}, {3, 4}}; [p setPositioningRect:r]; Rc o = [p positioningRect]; CHECK(o.o.x == 1 && o.o.y == 2 && o.s.w == 3 && o.s.h == 4);
    [p setAnimates:1]; CHECK([p animates] == 1);
    [p setDelegate:(id)p]; CHECK([p delegate] == (id)p);
    [p setDelegate:0]; CHECK([p delegate] == 0);
    [p close];
    id a = [NSSpellChecker sharedSpellChecker], b = [NSSpellChecker sharedSpellChecker];
    CHECK(a != 0 && a == b);
    printf(fails ? "FAIL generated_test\n" : "PASS generated_test\n");
    return fails != 0;
}
